    private static List<View> findAll(View view,String simple){List<View> result=new ArrayList<>();if(view.getClass().getSimpleName().equals(simple))result.add(view);if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)result.addAll(findAll(((ViewGroup)view).getChildAt(i),simple));return result;}
    private static Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
    private static void set(Object target,String name,Object value)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}
    private static Method method(Object target,String name,Class<?>...params)throws Exception{Method m=target.getClass().getDeclaredMethod(name,params);m.setAccessible(true);return m;}
